  class RingGeometry extends BufferGeometry {
    constructor(innerRadius = 0.5, outerRadius = 1, thetaSegments = 8, phiSegments = 1) {
      super();
      this.type = 'RingGeometry';
      const thetaSeg = Math.max(3, Math.floor(thetaSegments));
      const phiSeg = Math.max(1, Math.floor(phiSegments));
      const vertices = [], normals = [], uvs = [], indices = [];

      for (let j = 0; j <= phiSeg; j++) {
        const radius = innerRadius + (outerRadius - innerRadius) * (j / phiSeg);
        for (let i = 0; i <= thetaSeg; i++) {
          const segment = (i / thetaSeg) * Math.PI * 2;
          const x = radius * Math.cos(segment);
          const y = radius * Math.sin(segment);
          vertices.push(x, y, 0);
          normals.push(0, 0, 1);
          uvs.push((x / outerRadius + 1) / 2, (y / outerRadius + 1) / 2);
        }
      }

      for (let j = 0; j < phiSeg; j++) {
        const thetaSegmentLevel = j * (thetaSeg + 1);
        for (let i = 0; i < thetaSeg; i++) {
          const segment = i + thetaSegmentLevel;
          const a = segment;
          const b = segment + thetaSeg + 1;
          const c = segment + thetaSeg + 2;
          const d = segment + 1;
          indices.push(a, b, d);
          indices.push(b, c, d);
        }
      }

      this.setIndex(indices);
      this.setAttribute('position', new Float32BufferAttribute(vertices, 3));
      this.setAttribute('normal', new Float32BufferAttribute(normals, 3));
      this.setAttribute('uv', new Float32BufferAttribute(uvs, 2));
    }
  }
  THREE.RingGeometry = RingGeometry;

  class CircleGeometry extends BufferGeometry {
    constructor(radius = 1, segments = 8) {
      super();
      this.type = 'CircleGeometry';
      const seg = Math.max(3, Math.floor(segments));
      const vertices = [0, 0, 0], normals = [0, 0, 1], uvs = [0.5, 0.5], indices = [];

      for (let s = 0; s <= seg; s++) {
        const segment = (s / seg) * Math.PI * 2;
        const x = radius * Math.cos(segment);
        const y = radius * Math.sin(segment);
        vertices.push(x, y, 0);
        normals.push(0, 0, 1);
        uvs.push((x / radius + 1) / 2, (y / radius + 1) / 2);
      }

      for (let i = 1; i <= seg; i++) {
        indices.push(i, i + 1, 0);
      }

      this.setIndex(indices);
      this.setAttribute('position', new Float32BufferAttribute(vertices, 3));
      this.setAttribute('normal', new Float32BufferAttribute(normals, 3));
      this.setAttribute('uv', new Float32BufferAttribute(uvs, 2));
    }
  }
