  class TubeGeometry extends BufferGeometry {
    constructor(path, tubularSegments = 64, radius = 1, radialSegments = 8, closed = false) {
      super();
      this.type = 'TubeGeometry';
      this.parameters = { path, tubularSegments, radius, radialSegments, closed };

      const numPoints = tubularSegments + 1;
      const vertices = [], normals = [], uvs = [], indices = [];
      const frames = { tangents: [], normals: [], binormals: [] };

      // Compute Frenet frames along curve
      for (let i = 0; i < numPoints; i++) {
        const u = i / tubularSegments;
        const tangent = path.getTangentAt(u, new Vector3());
        frames.tangents.push(tangent);
      }

      // Compute Frenet frames along curve
      let initialNormal = new Vector3();
      const t0 = frames.tangents[0];
      const tx = Math.abs(t0.x), ty = Math.abs(t0.y), tz = Math.abs(t0.z);
      let minVal = Math.min(tx, ty, tz);
      if (minVal === tx) initialNormal.set(1, 0, 0);
      else if (minVal === ty) initialNormal.set(0, 1, 0);
      else initialNormal.set(0, 0, 1);
      const binormal0 = new Vector3().crossVectors(t0, initialNormal).normalize();
      initialNormal.crossVectors(binormal0, t0).normalize();
      frames.normals.push(initialNormal);
      frames.binormals.push(binormal0);

      for (let i = 1; i < numPoints; i++) {
        const tangent = frames.tangents[i];
        const prevTangent = frames.tangents[i - 1];
        const prevNormal = frames.normals[i - 1];
        const prevBinormal = frames.binormals[i - 1];

        const rotAxis = new Vector3().crossVectors(prevTangent, tangent);
        if (rotAxis.lengthSq() > 1e-6) {
          rotAxis.normalize();
          const dotVal = THREE.MathUtils.clamp(prevTangent.dot(tangent), -1, 1);
          const theta = Math.acos(dotVal);
          const q = new Quaternion().setFromAxisAngle(rotAxis, theta);
          const nextNormal = prevNormal.clone().applyQuaternion(q).normalize();
          frames.normals.push(nextNormal);
          frames.binormals.push(new Vector3().crossVectors(tangent, nextNormal).normalize());
        } else {
          frames.normals.push(prevNormal.clone());
          frames.binormals.push(prevBinormal.clone());
        }
      }

      // Generate tube vertices
      for (let i = 0; i <= tubularSegments; i++) {
        const u = i / tubularSegments;
        const P = path.getPointAt(u, new Vector3());
        const N = frames.normals[i];
        const B = frames.binormals[i];

        for (let j = 0; j <= radialSegments; j++) {
          const v = j / radialSegments * Math.PI * 2;
          const sin = Math.sin(v);
          const cos = -Math.cos(v);

          // Normal vector in cross section
          const normal = new Vector3();
          normal.x = (cos * N.x + sin * B.x);
          normal.y = (cos * N.y + sin * B.y);
          normal.z = (cos * N.z + sin * B.z);
          normal.normalize();
          normals.push(normal.x, normal.y, normal.z);

          // Vertex position
          const vertex = new Vector3().copy(P).addScaledVector(normal, radius);
          vertices.push(vertex.x, vertex.y, vertex.z);

          uvs.push(u, j / radialSegments);
        }
      }

      // Generate indices
      for (let j = 1; j <= tubularSegments; j++) {
        for (let i = 1; i <= radialSegments; i++) {
          const a = (radialSegments + 1) * (j - 1) + (i - 1);
          const b = (radialSegments + 1) * j + (i - 1);
          const c = (radialSegments + 1) * j + i;
          const d = (radialSegments + 1) * (j - 1) + i;

          indices.push(a, b, d);
          indices.push(b, c, d);
        }
      }

      this.setIndex(indices);
      this.setAttribute('position', new Float32BufferAttribute(vertices, 3));
      this.setAttribute('normal', new Float32BufferAttribute(normals, 3));
      this.setAttribute('uv', new Float32BufferAttribute(uvs, 2));
    }
  }
